                "O metabolismo energético converte substratos em ATP e precursores de síntese. Nutrientes não são utilizados com eficiência idêntica para manutenção, deposição de tecido e produção de leite. A bioquímica zootécnica conecta alimentação, metabolismo e composição dos produtos animais. As rotas funcionam de forma integrada e respondem ao estado fisiológico; compreender fluxos é mais útil que memorizar reações desconectadas. Oxidação e síntese dependem de enzimas, cofatores e regulação hormonal. Parte da energia se dissipa como calor; por isso, conteúdo energético de um alimento e energia retida pelo animal diferem. Como o conceito de energia metabólica e síntese tecidual ajuda a interpretar o exemplo? A resposta deve ligar o conceito às condições da situação e justificar a conclusão. Um esquema acompanha carbono de um carboidrato alimentar até oxidação ou deposição de gordura, destacando as transformações intermediárias e perdas envolvidas no processo."
