                "Proteínas corporais são continuamente sintetizadas e degradadas. Aminoácidos fornecem unidades para tecidos, enzimas e outras moléculas; nitrogênio excedente precisa ser transformado e eliminado. A bioquímica zootécnica conecta alimentação, metabolismo e composição dos produtos animais. As rotas funcionam de forma integrada e respondem ao estado fisiológico; compreender fluxos é mais útil que memorizar reações desconectadas. A utilização depende do perfil de aminoácidos disponíveis e da oferta energética. Em ruminantes, microrganismos modificam o fluxo de nitrogênio, conectando alimento, proteína microbiana e nutrientes absorvidos. Como o conceito de metabolismo de proteína e nitrogênio ajuda a interpretar o exemplo? A resposta deve ligar o conceito às condições da situação e justificar a conclusão. Uma comparação acadêmica relaciona oferta de aminoácidos e energia à síntese proteica, mostrando por que maior teor de proteína nem sempre significa maior deposição muscular."
