                "Fundamentos de Crescimento e estrutura do dossel",
                "Folhas, colmos e material morto compõem a estrutura do pasto. A interceptação de luz e a renovação de tecidos condicionam crescimento, qualidade e facilidade de apreensão pelo animal. O manejo de pastagens integra fisiologia das plantas, estrutura do dossel e comportamento de pastejo. Produção por área depende da interação entre oferta, qualidade, utilização e persistência do pasto ao longo das estações. Desfolha modifica área foliar e reservas; maturidade tende a alterar proporções de tecidos e valor nutritivo. O equilíbrio entre rebrota e remoção depende de espécie, fertilidade, clima e intensidade de utilização. Como o conceito de crescimento e estrutura do dossel ajuda a interpretar o exemplo? A resposta deve ligar o conceito às condições da situação e justificar a conclusão. Uma série de imagens didáticas compara pastos em estágios diferentes, relacionando folha disponível, alongamento de colmo e oportunidade de seleção durante o pastejo."
