                "type": "text",
                "title": "Resolução comentada",
                "paragraphs": [
                  "10×0,85=8,5 t de MS. Para fornecer 10 t após a mesma perda, seriam necessárias 10/0,85≈11,76 t inicialmente. Acrescentar apenas 15% a 10 t não compensa exatamente uma perda calculada sobre o estoque inicial."
                ]
